// Lambda@Edge: rewrite the request URI at the edge
export const handler = async (event) => {
  const req = event.Records[0].cf.request;
  if (req.uri === "/") req.uri = "/index.html";
  return req;
};

// CloudFront Function: redirect to HTTPS
function handler(event) {
  var req = event.request;
  return { statusCode: 301, headers: { location: { value: "https://" + req.headers.host.value + req.uri } } };
}
